settings.custom_css:
/* Modern Flat Filter CSS - No Shadow - Blue Version - Rubik Font */

/* Main container */
.wpc-filters-section {
  background-color: #ffffff;
  border-radius: 12px;
  padding: 20px;
  margin-bottom: 24px;
  font-family: 'Rubik', sans-serif;
  transition: all 0.3s ease;
  isolation: isolate;
  position: relative;
  border: 1px solid #eaeaea;
}

/* Filter header */
.wpc-filter-header {
  border-bottom: 1px solid #f0f0f0;
  padding-bottom: 12px;
  margin-bottom: 16px;
}

.wpc-filter-title {
  font-size: 18px;
  font-weight: 600;
  color: #333;
  margin: 0;
}

/* Filter list */
.wpc-filters-ul-list {
  list-style: none;
  padding: 0;
  margin: 0;
  max-height: 350px;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: #cdcdcd #f1f1f1;
}

/* Scrollbar for Webkit */
.wpc-filters-ul-list::-webkit-scrollbar {
  width: 8px;
}

.wpc-filters-ul-list::-webkit-scrollbar-track {
  background: #f1f1f1;
  border-radius: 4px;
}

.wpc-filters-ul-list::-webkit-scrollbar-thumb {
  background: #cdcdcd;
  border-radius: 4px;
}

.wpc-filters-ul-list::-webkit-scrollbar-thumb:hover {
  background: #aaaaaa;
}

/* List item */
.wpc-checkbox-item {
  margin-bottom: 12px;
  transition: transform 0.2s ease;
  position: relative;
}

.wpc-checkbox-item:hover {
  transform: translateY(-2px);
}

/* Term content */
.wpc-term-item-content-wrapper {
  display: flex;
  align-items: center;
}

/* Checkbox styling */
.wpc-term-item-content-wrapper input[type="checkbox"] {
  -webkit-appearance: none;
  appearance: none;
  background-color: #fff;
  margin: 0;
  width: 20px;
  height: 20px;
  border: 2px solid #e0e0e0;
  border-radius: 4px;
  display: grid;
  place-content: center;
  margin-right: 10px;
  cursor: pointer;
  transition: all 0.2s ease;
  position: relative;
}

.wpc-term-item-content-wrapper input[type="checkbox"]:checked {
  background-color: #297CBB;
  border-color: #297CBB;
}

/* Checkbox tik işareti */
.wpc-term-item-content-wrapper input[type="checkbox"]:checked::before {
  content: "✓";
  color: white;
  font-size: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  width: 100%;
  position: absolute;
  top: 0;
  left: 0;
}

.wpc-term-item-content-wrapper input[type="checkbox"]:focus {
  outline: 2px solid rgba(41, 124, 187, 0.3);
}

.wpc-term-item-content-wrapper input[type="checkbox"]:hover {
  border-color: #297CBB;
}

/* Label styling */
.wpc-term-item-content-wrapper label {
  display: flex;
  align-items: center;
  cursor: pointer;
  width: 100%;
  font-size: 15px;
  color: #444;
  font-weight: normal;
  transition: font-weight 0.2s ease;
}

/* SEÇİLİ OLANLAR BOLD */
.wpc-term-item-content-wrapper input[type="checkbox"]:checked + label {
  font-weight: 700;
}

/* Link styling */
.wpc-filter-link {
  color: #444;
  text-decoration: none !important;
  flex-grow: 1;
  border-bottom: none !important;
  box-shadow: none !important;
  display: inline-block;
}

/* Remove hover underline */
.wpc-filter-link,
.wpc-filter-link:hover,
.wpc-filter-link:focus,
.wpc-filter-link:active,
.wpc-filter-link:visited,
a.wpc-filter-link,
a.wpc-filter-link:hover,
a.wpc-filter-link:focus,
a.wpc-filter-link:active,
a.wpc-filter-link:visited,
.wpc-term-item-content-wrapper label a,
.wpc-term-item-content-wrapper label a:hover,
.wpc-term-item-content-wrapper label a:focus,
.wpc-term-item-content-wrapper label a:active,
.wpc-term-item-content-wrapper label a:visited {
  text-decoration: none !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  outline: none !important;
  background-image: none !important;
  position: relative;
}

/* Remove pseudo-elements */
.wpc-filter-link::after,
.wpc-filter-link::before,
.wpc-term-item-content-wrapper label a::after,
.wpc-term-item-content-wrapper label a::before {
  display: none !important;
  content: none !important;
}

/* Count styling */
.wpc-term-count {
  font-size: 13px;
  color: #888;
  margin-left: 5px;
  background-color: #d8ecfa;
  border-radius: 12px;
  padding: 1px 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 24px;
}

/* Hide brackets */
.wpc-term-count-brackets-open,
.wpc-term-count-brackets-close {
  display: none;
}

/* Empty counts */
.wpc-term-count-0 .wpc-filter-link,
.wpc-term-count-0 .wpc-term-count {
  color: #bbb;
}
/* Hoverda seçeneğin yazısı siyah ve bold olsun */
.wpc-term-item-content-wrapper a.wpc-filter-link:hover {
  color: #000!important;
  
}
